def head(title, desc, prefix=''):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)} | Puspamitra Mishra</title><meta name="description" content="{escape(desc)}"><meta name="theme-color" content="#173f3e"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(desc)}"><meta property="og:type" content="website"><link rel="icon" href="{prefix}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{prefix}styles.css"><script src="{prefix}script.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a>'''

def header(prefix=''):
    return f'''<div class="wrap"><header class="header"><a class="brand" href="{prefix}index.html" aria-label="Puspamitra Mishra home"><span class="monogram">pm<span class="sr-only"></span></span>Puspamitra Mishra<span style="color:var(--teal)">.</span></a><button class="menu" aria-expanded="false" aria-controls="navigation">Menu ☰</button><nav class="nav" id="navigation" aria-label="Main navigation"><a href="{prefix}index.html#about">About</a><a href="{prefix}index.html#projects">AI projects</a><a href="{prefix}index.html#experience">Experience</a><a class="nav-contact" href="{prefix}index.html#contact">Let’s connect ↗</a></nav></header></div>'''

def footer(prefix=''):
    return f'''<footer class="footer wrap"><span>© 2026 Puspamitra Mishra · Architecture with purpose.</span><div class="footer-links"><a href="https://www.linkedin.com/in/puspamitra-mishra-6b186b29/">LinkedIn ↗</a><a href="mailto:puspamitra.mishra@gmail.com">Email ↗</a><a href="#main">Back to top ↑</a></div></footer></body></html>'''

def metrics(items, cls=''):
    return f'<div class="metrics {cls}">' + ''.join(f'<div class="metric"><strong>{a}</strong><span>{b}</span></div>' for a,b in items) + '</div>'

